get_checkout_page.code:
var response = await client.CheckoutPage.GetCheckoutPageAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var checkoutPage = (IReadOnlyDictionary<string, object?>)body["checkout_page"]!;
var orderSummary = (IReadOnlyDictionary<string, object?>)checkoutPage["order_summary"]!;
Console.WriteLine(orderSummary["enable_payment_expand_view"]);

patch_checkout_page.code:
var response = await client.CheckoutPage.PatchCheckoutPageAsync(new Dictionary<string, object?>
{
    ["checkout_page"] = new Dictionary<string, object?>
    {
        ["order_summary"] = new Dictionary<string, object?> { ["enable_payment_expand_view"] = false },
        ["customer_checkout"] = new Dictionary<string, object?> { ["multiple_shipping_methods"] = true },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var checkoutPage = (IReadOnlyDictionary<string, object?>)body["checkout_page"]!;
var orderSummary = (IReadOnlyDictionary<string, object?>)checkoutPage["order_summary"]!;
Console.WriteLine(orderSummary["enable_payment_expand_view"]);

